solution:
public class ValidadorURL {
    public static void main(String[] args) {
        String url = "https://www.ejemplo.com/java/tutoriales";

        StringBuilder informe = new StringBuilder();
        informe.append("=== URL Report ===\n");
        informe.append("URL: ").append(url).append("\n");

        boolean usaHTTPS = url.startsWith("https://");
        informe.append("HTTPS protocol: ").append(usaHTTPS ? "✅ Yes" : "❌ No").append("\n");

        boolean extensionValida = url.endsWith(".com") || url.endsWith(".org");
        informe.append("Valid extension: ").append(extensionValida ? "✅ Yes" : "❌ No").append("\n");

        int inicioDominio = url.indexOf("//") + 2;
        int finDominio = url.indexOf("/", inicioDominio);
        String dominio = url.substring(inicioDominio, finDominio);
        informe.append("Domain: ").append(dominio).append("\n");

        boolean tienePunto = dominio.contains(".");
        informe.append("Domain format: ").append(tienePunto ? "✅ Valid" : "❌ Invalid").append("\n");

        String[] partes = url.substring(inicioDominio).split("/");
        informe.append("Path segments: ").append(partes.length - 1).append("\n");

        boolean urlValida = usaHTTPS && extensionValida && tienePunto;
        informe.append("\nResult: ").append(urlValida ? "✅ VALID URL" : "❌ INVALID URL");

        System.out.println(informe);
    }
}
